import React, { useState } from 'react';
import { httpsCallable } from 'firebase/functions';
import { functions } from '../firebase';
import './DemoPopup.css';

const DemoPopup = ({ isOpen, onClose }) => {
  const [name, setName] = useState('');
  const [email, setEmail] = useState('');
  const [congregation, setCongregation] = useState('');
  const [message, setMessage] = useState('');
  const [status, setStatus] = useState('idle');
  const [errorMessage, setErrorMessage] = useState('');

  if (!isOpen) return null;

  const handleSubmit = async (e) => {
    e.preventDefault();
    setStatus('submitting');
    setErrorMessage('');

    try {
      // 1. Log attempt
      console.log("Attempting to call handleDemoRequest with:", { name, email, congregation });

      // 2. Call function (Force region if necessary, default is usually us-central1)
      const handleDemoRequest = httpsCallable(functions, 'handleDemoRequest');
      
      const result = await handleDemoRequest({ 
        name, 
        email, 
        congregation, 
        message 
      });

      console.log("Success result:", result);
      setStatus('success');
      
      // Reset form
      setTimeout(() => {
        onClose();
        setStatus('idle');
        setName('');
        setEmail('');
        setCongregation('');
        setMessage('');
      }, 2500);

    } catch (error) {
      // 3. Detailed Error Logging
      console.error("FIREBASE ERROR:", error);
      console.error("ERROR CODE:", error.code);
      console.error("ERROR MESSAGE:", error.message);
      console.error("ERROR DETAILS:", error.details);

      setStatus('error');
      
      // Friendly messages based on common issues
      if (error.code === 'not-found') {
        setErrorMessage("Function not found. Ensure the backend is deployed.");
      } else if (error.code === 'permission-denied') {
        setErrorMessage("Permission denied. Check Firebase security rules.");
      } else {
        setErrorMessage(`Error: ${error.message || 'Something went wrong. Please try again.'}`);
      }
    }
  };

  return (
    <div className="demo-popup-overlay" onClick={onClose}>
      <div className="demo-popup-content" onClick={(e) => e.stopPropagation()}>
        <button className="demo-popup-close" onClick={onClose}>&times;</button>
        
        {status === 'success' ? (
          <div className="success-message">
            <h2 className="serif-italic">Blessings.</h2>
            <p>Your request has been received. We will be in touch shortly.</p>
          </div>
        ) : (
          <>
            <h2>Request a Demo</h2>
            <p>Join the movement of faithful coordination.</p>
            <form onSubmit={handleSubmit}>
              <div className="form-group">
                <label htmlFor="name">Name</label>
                <input 
                  type="text" 
                  id="name" 
                  value={name} 
                  onChange={(e) => setName(e.target.value)} 
                  required 
                  placeholder="The Rev. John Doe"
                />
              </div>
              <div className="form-group">
                <label htmlFor="email">Email</label>
                <input 
                  type="email" 
                  id="email" 
                  value={email} 
                  onChange={(e) => setEmail(e.target.value)} 
                  required 
                  placeholder="vicar@stjude.org"
                />
              </div>
              <div className="form-group">
                <label htmlFor="congregation">Congregation</label>
                <input 
                  type="text" 
                  id="congregation" 
                  value={congregation} 
                  onChange={(e) => setCongregation(e.target.value)} 
                  placeholder="St. Jude's Episcopal"
                />
              </div>
              <div className="form-group">
                <label htmlFor="message">Message</label>
                <textarea 
                  id="message" 
                  value={message} 
                  onChange={(e) => setMessage(e.target.value)} 
                  required 
                  placeholder="How can we help your community?"
                ></textarea>
              </div>
              <button 
                type="submit" 
                className="btn-primary" 
                disabled={status === 'submitting'}
              >
                {status === 'submitting' ? 'Sending...' : 'Send Request'}
              </button>
              {status === 'error' && (
                <p className="error-text">{errorMessage}</p>
              )}
            </form>
          </>
        )}
      </div>
    </div>
  );
};

export default DemoPopup;
