import React, { useRef } from 'react';
import { Canvas, useFrame } from '@react-three/fiber';
import { ContactShadows, Float } from '@react-three/drei';

const DetailedCar = () => {
  const group = useRef();

  useFrame((state) => {
    const t = state.clock.getElapsedTime();
    if (group.current) group.current.rotation.y = t * 0.4;
    if (group.current) group.current.position.y = Math.sin(t) * 0.05;
  });

  return (
    <group ref={group} scale={0.75}>
      {/* Chassis */}
      <mesh position={[0, 0.5, 0]} castShadow>
        <boxGeometry args={[3.2, 0.5, 1.4]} />
        <meshStandardMaterial color="#1a1a1a" metalness={0.9} roughness={0.1} />
      </mesh>
      
      {/* Upper Cabin */}
      <mesh position={[-0.2, 0.95, 0]} castShadow>
        <boxGeometry args={[1.8, 0.6, 1.2]} />
        <meshStandardMaterial color="#050505" metalness={1} roughness={0} />
      </mesh>

      {/* Rear Spoiler */}
      <mesh position={[-1.4, 0.8, 0]} castShadow>
        <boxGeometry args={[0.4, 0.05, 1.2]} />
        <meshStandardMaterial color="#111" />
      </mesh>

      {/* Headlights - Emissive glow */}
      {[ [1.6, 0.5, 0.4], [1.6, 0.5, -0.4] ].map((pos, i) => (
        <mesh key={i} position={pos}>
          <boxGeometry args={[0.05, 0.15, 0.3]} />
          <meshStandardMaterial color="#fff" emissive="#fff" emissiveIntensity={4} />
        </mesh>
      ))}

      {/* Tail Lights - Red emissive glow */}
      {[ [-1.6, 0.55, 0.4], [-1.6, 0.55, -0.4] ].map((pos, i) => (
        <mesh key={i} position={pos}>
          <boxGeometry args={[0.05, 0.1, 0.3]} />
          <meshStandardMaterial color="#ff0000" emissive="#ff0000" emissiveIntensity={2} />
        </mesh>
      ))}

      {/* Wheels */}
      {[[-1.1, 0.3, 0.75], [1.1, 0.3, 0.75], [-1.1, 0.3, -0.75], [1.1, 0.3, -0.75]].map((pos, i) => (
        <mesh key={i} position={pos} rotation={[Math.PI / 2, 0, 0]} castShadow>
          <cylinderGeometry args={[0.35, 0.35, 0.25, 32]} />
          <meshStandardMaterial color="#050505" />
        </mesh>
      ))}

      {/* Floating Cross */}
      <group position={[0, 3, 0]}>
        <Float speed={2.5} rotationIntensity={0.3} floatIntensity={0.6}>
          <mesh castShadow>
            <boxGeometry args={[0.08, 1.0, 0.08]} />
            <meshStandardMaterial color="#276ef1" metalness={1} roughness={0} />
          </mesh>
          <mesh position={[0, 0.25, 0]} castShadow>
            <boxGeometry args={[0.6, 0.08, 0.08]} />
            <meshStandardMaterial color="#276ef1" metalness={1} roughness={0} />
          </mesh>
        </Float>
      </group>
    </group>
  );
};

const ThreeDCar = () => {
  return (
    <div className="threed-car-visual-container" style={{ position: 'relative', width: '100%', height: '600px' }}>
      <Canvas shadows camera={{ position: [10, 8, 10], fov: 30 }}>
        <ambientLight intensity={1} />
        <pointLight position={[10, 10, 10]} intensity={2} castShadow />
        <directionalLight position={[-10, 10, 5]} intensity={1} />
        <DetailedCar />
        <ContactShadows position={[0, 0, 0]} opacity={0.4} scale={20} blur={2.5} far={4} />
      </Canvas>
    </div>
  );
};

export default ThreeDCar;
