import React, { useState, useEffect, useRef, useMemo } from 'react';
import './DrivingCar.css';
import './Bendy.css';
import './WorldElements.css';

const BendyPerson = ({ style }) => (
  <div className="bendy-figure active world-benny" style={style}>
    <div className="bendy-container">
      <div className="bendy-head"></div>
      <div className="bendy-body-group">
        <div className="bendy-torso"></div>
        <div className="bendy-arm arm-left"></div>
        <div className="bendy-arm arm-right"></div>
        <div className="bendy-leg leg-left"></div>
        <div className="bendy-leg leg-right"></div>
      </div>
    </div>
  </div>
);

const DrivingCar = () => {
  const [visibleGroups, setVisibleGroups] = useState({ lights: false });
  const [treads, setTreads] = useState([]);
  const [crossPos, setCrossPos] = useState(8000); 
  const [isPhoneActive, setIsPhoneActive] = useState(false);
  const [isPastPhone, setIsPastPhone] = useState(false);
  
  const carRef = useRef();
  const initialY = 540;
  const targetY = useRef(initialY);
  const currentY = useRef(initialY);
  const lastTreadPos = useRef(initialY);
  const requestRef = useRef();

  // Create persistent road-crossers
  const roadCrossers = useMemo(() => {
    return Array.from({ length: 15 }).map((_, i) => ({
      id: i,
      y: 1200 + (i * 450), // Distributed down the road
      delay: Math.random() * 5,
      speed: 10 + Math.random() * 5,
      scale: 0.3 + Math.random() * 0.2
    }));
  }, []);

  useEffect(() => {
    const handlePhoneActive = (e) => setIsPhoneActive(e.detail.active);
    window.addEventListener('phone-scroll-active', handlePhoneActive);
    return () => window.removeEventListener('phone-scroll-active', handlePhoneActive);
  }, []);

  useEffect(() => {
    const updateCrossPos = () => {
      const cross = document.querySelector('.cross-placeholder');
      if (cross) {
        const rect = cross.getBoundingClientRect();
        const scrollTop = window.pageYOffset || document.documentElement.scrollTop;
        setCrossPos(rect.top + scrollTop + 30); 
      }
    };
    updateCrossPos();
    window.addEventListener('load', updateCrossPos);
    window.addEventListener('resize', updateCrossPos);
    return () => {
      window.removeEventListener('load', updateCrossPos);
      window.removeEventListener('resize', updateCrossPos);
    };
  }, []);

  useEffect(() => {
    const handleScrollVisibility = () => {
      const cross = document.querySelector('.cross-placeholder');
      if (cross) {
        const rect = cross.getBoundingClientRect();
        setIsPastPhone(rect.bottom < 100);
      }
    };
    window.addEventListener('scroll', handleScrollVisibility);
    return () => window.removeEventListener('scroll', handleScrollVisibility);
  }, []);

  const roadPoints = useMemo(() => {
    const w = window.innerWidth;
    return [ [w * 0.5, initialY], [w * 0.5, crossPos - 200] ];
  }, [crossPos, initialY]);

  const roadPathString = useMemo(() => `M ${roadPoints.map(p => `${p[0]} ${p[1]}`).join(' L ')}`, [roadPoints]);

  useEffect(() => {
    const handleScroll = () => {
      const winScroll = window.scrollY;
      const viewportOffset = window.innerHeight * 0.35;
      const scrollTarget = winScroll + viewportOffset;
      targetY.current = Math.max(initialY, Math.min(crossPos, scrollTarget));
      if (winScroll > 600 && !visibleGroups.lights) setVisibleGroups({ lights: true });
    };

    const animate = () => {
      currentY.current += (targetY.current - currentY.current) * 0.08;
      if (carRef.current) {
        carRef.current.style.transform = `translate3d(${window.innerWidth * 0.5}px, ${currentY.current}px, 0) translate(-50%, -50%) rotate(90deg)`;
      }
      
      const distSinceLast = Math.abs(currentY.current - lastTreadPos.current);
      if (distSinceLast > 25 && !isPhoneActive) {
        const newTreads = [ { dx: 18, dy: -15 }, { dx: 18, dy: 15 }, { dx: -18, dy: -15 }, { dx: -18, dy: 15 } ].map((off, idx) => ({
          id: `${Date.now()}-${idx}`,
          x: window.innerWidth * 0.5 + off.dy,
          y: currentY.current + off.dx,
          life: 1.0
        }));
        setTreads(prev => [...newTreads, ...prev].slice(0, 100));
        lastTreadPos.current = currentY.current;
      }
      requestRef.current = requestAnimationFrame(animate);
    };

    window.addEventListener('scroll', handleScroll, { passive: true });
    requestRef.current = requestAnimationFrame(animate);
    return () => {
      window.removeEventListener('scroll', handleScroll);
      cancelAnimationFrame(requestRef.current);
    };
  }, [crossPos, isPhoneActive, visibleGroups.lights]);

  useEffect(() => {
    const decay = setInterval(() => {
      setTreads(prev => prev.map(t => ({ ...t, life: t.life - 0.04 })).filter(t => t.life > 0));
    }, 50);
    return () => clearInterval(decay);
  }, []);

  return (
    <>
      <div className={`world-elements-container ${isPhoneActive ? 'road-broken' : ''} ${isPastPhone ? 'hidden' : ''}`}>
        <svg className="road-svg" width="100%" height="100%">
          <path className="road-path-outer" d={roadPathString} />
          <path className="road-path-inner" d={roadPathString} />
        </svg>

        {treads.map(tread => (
          <div key={tread.id} className="tire-tread" style={{ left: `${tread.x}px`, top: `${tread.y}px`, opacity: tread.life * 0.1 }} />
        ))}
      </div>

      <div ref={carRef} className={`driving-car moving ${isPhoneActive || isPastPhone ? 'hidden' : ''}`}>
        <div className="car-body">
          <div className="car-chassis">
            <div className="wheel wheel-fl"></div>
            <div className="wheel wheel-fr"></div>
            <div className="wheel wheel-rl"></div>
            <div className="wheel wheel-rr"></div>
            <div className="car-roof"></div>
            <div className="headlight headlight-l"></div>
            <div className="headlight headlight-r"></div>
          </div>
        </div>
      </div>
    </>
  );
};

export default DrivingCar;
